            'enquiry-map' => array(
                'title' => 'How the enquiry process works',
                'content' => '<section><h2>From enquiry to lessons</h2><ol><li><strong>Book online:</strong> Share the learner’s level, subjects, goals and preferred times.</li><li><strong>Choose:</strong> Select weekly, biweekly or monthly prepayment.</li><li><strong>Pay:</strong> The parent pays securely before the lesson block begins.</li><li><strong>Activate:</strong> Receive the student login and confirmed timetable.</li><li><strong>Learn:</strong> Begin live lessons and review progress over time.</li></ol></section>',
