            'crash-registration' => array(
                'title' => 'Register for the 12-week crash course',
                'content' => '<section><h2>Student details</h2>[ln_form id="crash-registration"]</section><section><h2>Next step</h2><p>The team will review subject and tutor availability, then contact the parent or guardian about the upcoming intake.</p></section>',
