		),
		'posts' => array(
            'post-crash-course' => array(
                'title' => 'The 12-week crash course: a fast track to exam confidence',
                'date' => '12 November 2025',
                'content' => '<section><h2>Why the final 12 weeks matter</h2><p>Students and private candidates can feel overwhelmed when the syllabus is broad and time is short. A defined weekly route turns that pressure into clear priorities.</p></section><section><h2>Structured and time-bound</h2><p>A weekly plan helps cover the syllabus before exams and makes progress easier to review.</p></section><section><h2>Live, interactive classes</h2><p>Lessons are delivered live and can respond to the student\'s questions, pace and current gaps.</p></section><section><h2>Exam-focused strategy</h2><p>Tutors emphasise mark schemes, command words, timing and the structure of strong answers.</p></section><section><h2>Flexible online learning</h2><p>Students can attend from home, including private and homeschooling candidates.</p></section><section><h2>What the programme builds</h2><ul class="list"><li>Confidence in priority topics</li><li>Smarter revision habits</li><li>Past-paper familiarity</li><li>Readiness for timed exams</li></ul></section><section><h2>Next intake</h2><p>Intake dates are confirmed according to exam series and subject availability. Ask the team for the next suitable start.</p></section>',
                'lead' => 'A structured, focused and expert-led revision programme can bring clarity when the examination window is approaching.',
            ),
            'post-igcse-maths' => array(
                'title' => 'Best way to prepare for IGCSE Maths',
                'date' => '29 September 2023',
                'content' => '<section><h2>1. Know the syllabus</h2><p>Turn the official specification into a checklist. Work through Algebra, Geometry, Statistics, Trigonometry and every other listed topic one by one.</p></section><section><h2>2. Use past papers as your main tool</h2><ul class="list"><li>Work through several years where available</li><li>Check each answer against the mark scheme</li><li>Return to difficult questions until the method feels familiar</li></ul></section><section><h2>3. Master formulas and methods</h2><p>Create a formula sheet, revise it regularly and practise applying each formula in real questions rather than memorising it in isolation.</p></section><section><h2>4. Practise under timed conditions</h2><p>Use the exact timing and calculator rules for the paper. Learn how to recover when a question takes too long.</p></section><section><h2>5. Fix weak areas quickly</h2><p>Do not avoid topics such as Trigonometry or Probability. Study a worked example, complete a focused question set and retest later.</p></section><section><h2>6. Stay consistent</h2><p>Regular focused practice is more effective than last-minute cramming. Mix short topic reviews with past-paper questions.</p></section><section><h2>Final tip</h2><div class="quote">Maths improves through practice. The more carefully you solve and review, the stronger your methods become.</div></section>',
                'lead' => 'A clear strategy builds both confidence and accuracy in IGCSE Mathematics.',
            ),
            'post-study-guide' => array(
                'title' => 'Best way to study for IGCSEs',
                'date' => '29 September 2023',
                'content' => '<section><h2>1. Start with the syllabus</h2><p>The syllabus is the exam roadmap. Print it or track it digitally, mark completed topics and keep revision inside the exact specification.</p></section><section><h2>2. Use past papers</h2><ul class="list"><li>Practise five to ten years where available</li><li>Mark answers with the official mark scheme</li><li>Redo papers after correcting errors</li></ul></section><section><h2>3. Revise actively</h2><ul class="list"><li>Create flashcards for formulas, definitions and case studies</li><li>Use mind maps for connected topics</li><li>Teach the idea to a friend or family member</li></ul></section><section><h2>4. Manage revision time</h2><p>Two or three focused hours can be more useful than six distracted hours. Try work blocks of 25–50 minutes followed by a short break.</p></section><section><h2>5. Fix weak areas</h2><p>Difficult chapters can make the difference between grade boundaries. Give them extra practice and ask for help before the exam is close.</p></section><section><h2>6. Practise under exam conditions</h2><p>Time complete papers, use only allowed materials and review both knowledge gaps and time-management choices.</p></section><section><h2>Where to get more help</h2><p>The Learning Net offers subject guides, crash courses and personalised study plans for IGCSE and A-Level learners.</p></section>',
                'lead' => 'Smart, colourful and exam-focused strategies can outperform long, unfocused study hours.',
            ),
            'post-a-level-maths' => array(
                'title' => 'How to tackle tricky A-Level Maths questions',
                'date' => '19 September 2023',
                'content' => '<section><h2>Why are the questions difficult?</h2><ul class="list"><li>They combine topics such as calculus, trigonometry and vectors</li><li>They present familiar mathematics in unfamiliar contexts</li><li>They require a non-obvious starting point</li><li>They expose gaps in earlier GCSE or A-Level foundations</li></ul></section><section><h2>Step 1: Deconstruct the question</h2><ul class="list"><li>Read twice and note command words</li><li>Highlight given values, variables and conditions</li><li>Write down the exact outcome the question asks for</li></ul></section><section><h2>Step 2: Formulate a plan</h2><ul class="list"><li>Recall connected formulas or theorems</li><li>Break the problem into smaller steps</li><li>Try a different representation if the first route stalls</li></ul></section><section><h2>Step 3: Show working clearly</h2><ul class="list"><li>Write numbers and variables legibly</li><li>Show each meaningful step</li><li>State assumptions</li><li>Use correct mathematical notation</li></ul></section><section><h2>Step 4: Check and reflect</h2><ul class="list"><li>Ask whether the result is reasonable</li><li>Reread the required outcome</li><li>Check algebra, signs, units and substitutions</li></ul></section><section><h2>Step 5: Practise deliberately</h2><ul class="list"><li>Use later questions from past papers</li><li>Target weak areas such as specific calculus or proof skills</li><li>Get feedback from a teacher or tutor</li><li>Keep an error log and redo the question</li></ul></section><section><h2>Final thought</h2><p>Deconstructing, planning, showing working and checking can turn an intimidating question into a sequence of manageable decisions.</p></section>',
                'lead' => 'Tricky questions test connected understanding, not only the recall of a formula.',
            ),
            'post-revision-tips' => array(
                'title' => '10 proven tips to boost IGCSE revision success',
                'date' => '13 September 2023',
                'content' => '<section><h2>1. Start with expert resources</h2><p>Use structured courses, revision guides and past-paper practice made for the correct IGCSE specification. Build a timetable before revision becomes overwhelming.</p><div class="quote">A structured timetable prevents overwhelm and keeps you consistent.</div></section><section><h2>2. Use active recall</h2><p>Do not only reread notes. Test yourself with flashcards, blurting and practice questions.</p></section><section><h2>3. Master spaced repetition</h2><p>Revisit material after increasing intervals — for example after one day, three days, one week and two weeks. Tools such as Anki or Quizlet can support this routine.</p></section><section><h2>4. Create mind maps and visual aids</h2><p>Use diagrams and maps to show how topics connect and to strengthen visual memory.</p></section><section><h2>5. Take regular, useful breaks</h2><p>Try a focused block such as 25 minutes of study followed by a five-minute break, then take a longer break after four rounds.</p></section><section><h2>6. Practise with past papers</h2><p>Work under timed conditions, check the official mark scheme and turn every missed mark into a revision task.</p></section><section><h2>7. Find a study partner</h2><p>Peer discussion can increase motivation. Explaining a topic to someone else is one of the best tests of understanding.</p></section><section><h2>8. Look after your health</h2><ul class="list"><li>Aim for seven to nine hours of sleep</li><li>Eat regular balanced meals</li><li>Use movement and exercise to reduce stress and restore attention</li></ul></section><section><h2>9. Understand, do not just memorise</h2><p>IGCSE questions often test application and analysis. Ask why a method works and when it should be used.</p></section><section><h2>10. Stay constructive</h2><p>Track small wins, respond to mistakes and remember that exams are one stage in a longer learning journey.</p></section>',
                'lead' => 'Use these practical habits to make revision more active, consistent and manageable.',
            ),
            'post-one-to-one' => array(
                'title' => 'Why one-on-one learning can outperform group classes for IGCSE',
                'date' => '24 March 2023',
                'content' => '<section><h2>1. A tailored learning experience</h2><p>Group classes follow a pace for many learners. One-to-one teaching can focus on the student\'s exact strengths, gaps and preferred way of learning.</p><ul class="list"><li>Prioritise the areas that need most improvement</li><li>Adapt explanations to the learner</li><li>Adjust lesson plans as progress changes</li></ul></section><section><h2>2. More interaction and confidence</h2><p>Some students hesitate to ask questions in a large class. Individual sessions create space for open discussion, immediate correction and deeper clarification.</p></section><section><h2>3. Improved focus and attention</h2><p>The tutor\'s attention stays on one student. Fewer classroom distractions can increase concentration, participation and retention.</p></section><section><h2>4. Personalised exam strategies</h2><ul class="list"><li>Target revision using past-paper performance</li><li>Practise time management</li><li>Complete timed questions</li><li>Learn techniques for different question types</li></ul></section><section><h2>5. Greater flexibility</h2><p>Private lessons can be arranged around the learner\'s schedule and can spend longer on difficult topics rather than following a fixed class timetable.</p></section><section><h2>6. A stronger student–tutor relationship</h2><p>Consistent individual support can build trust, accountability and motivation. A tutor who knows the learner well can notice both academic and emotional barriers to progress.</p></section><section><h2>Final thoughts</h2><p>Group teaching can be useful, but one-to-one tuition provides focused attention, customised strategy and a quieter environment for IGCSE preparation.</p></section>',
                'lead' => 'Individual tutoring changes the pace, focus and feedback available during a demanding qualification.',
            ),
            'post-igcse-revision' => array(
                'title' => 'Ultimate guide to IGCSE revision',
                'date' => '3 March 2023',
                'content' => '<section><h2>1. Understand the exam format</h2><p>Before revising, confirm the paper structure for every subject. IGCSE exams can include multiple-choice questions, structured written responses, data analysis, case studies and practical assessments.</p></section><section><h2>2. Choose the right revision resources</h2><p>Use textbooks, workbooks, revision notes, video tutorials, quizzes and guided lessons that match the precise syllabus. Avoid mixing boards or outdated specifications.</p></section><section><h2>3. Make past papers central</h2><p>Past papers reveal question styles, recurring themes and time pressure.</p><ol><li><strong>Simulate exam conditions:</strong> Work under the correct time limit.</li><li><strong>Review the mark scheme:</strong> Understand where each mark comes from.</li><li><strong>Identify weak areas:</strong> Record topics and question types that caused difficulty.</li><li><strong>Repeat:</strong> Redo missed questions until the method is secure.</li></ol></section><section><h2>4. Study actively</h2><h3>Active recall and mind maps</h3><ul class="list"><li>Use flashcards to test rather than reread</li><li>Build mind maps to link related concepts</li></ul><h3>Discuss and explain</h3><p>Study with peers and explain difficult ideas aloud. Teaching another person is a powerful test of understanding.</p></section><section><h2>5. Prepare an exam strategy</h2><ul class="list"><li>Allocate time to each question</li><li>Use real-world examples where they strengthen an answer</li><li>Understand command words such as explain, evaluate and compare</li><li>Leave time to check calculations and written responses</li></ul></section><section><h2>Final thoughts</h2><p>Effective preparation depends on consistency, accurate materials and honest review of mistakes. Combine revision notes with past-paper practice and seek expert help when a topic stays unclear.</p></section>',
                'lead' => 'The best IGCSE revision combines the right resources with repeated retrieval, past-paper practice and careful review.',
            ),
